class SQLiteAcceptanceRaceTests(TransactionTestCase):
    reset_sequences=True
    def setUp(self):
        self.gov=Organization.objects.create(name='Race Response Office',kind='GOV')
        self.official=User.objects.create_user('race.official@test.local',password='password123'); Profile.objects.create(user=self.official,role='GOV',organization=self.gov,approval='APPROVED')
    def _race_acceptances(self,requests):
        barrier=Barrier(len(requests)+1)
        clients=[]
        for user_id,_ in requests:
            client=Client(); client.force_login(User.objects.get(pk=user_id)); clients.append(client)
        def submit(client,emergency_id):
            close_old_connections()
            try:
                barrier.wait(timeout=15)
                response=client.post(f'/api/emergencies/{emergency_id}/accept/',data='{}',content_type='application/json')
                return response.status_code
            finally: close_old_connections()
        with ThreadPoolExecutor(max_workers=len(requests)) as pool:
            futures=[pool.submit(submit,client,request[1]) for client,request in zip(clients,requests)]
            barrier.wait(timeout=15)
            return sorted(future.result(timeout=30) for future in futures)
    def test_concurrent_acceptance_has_one_winner_on_sqlite(self):
        ngo=Organization.objects.create(name='Race Relief NGO',kind='NGO')
        coordinator=User.objects.create_user('race.coordinator@test.local',password='password123'); Profile.objects.create(user=coordinator,role='NGO',organization=ngo,approval='APPROVED')
        emergency=Emergency.objects.create(reference='DR-RACE-ACCEPT',reporter=self.official,category='Flood',description='Race test',location='Ward 1')
        statuses=self._race_acceptances([(self.official.pk,emergency.pk),(coordinator.pk,emergency.pk)])
        emergency.refresh_from_db()
        if emergency.status=='OPEN':
            retry=Client(); retry.force_login(self.official)
            statuses.append(retry.post(f'/api/emergencies/{emergency.pk}/accept/',data='{}',content_type='application/json').status_code)
            emergency.refresh_from_db()
        self.assertEqual(statuses.count(200),1); self.assertEqual(emergency.status,'ACCEPTED')
        self.assertIn(emergency.accepted_by_id,(self.gov.pk,ngo.pk))
        self.assertEqual(EmergencyEvent.objects.filter(emergency=emergency,event_type='ACCEPTED').count(),1)
    def _race_assignments(self,requests):
        barrier=Barrier(len(requests)+1)
        clients=[]
        for user_id,_,_ in requests:
            client=Client(); client.force_login(User.objects.get(pk=user_id)); clients.append(client)
        def submit(client,emergency_id,payload):
            close_old_connections()
            try:
                barrier.wait(timeout=15)
                response=client.post(f'/api/emergencies/{emergency_id}/assign/',data=json.dumps(payload),content_type='application/json')
                return response.status_code
            finally: close_old_connections()
        with ThreadPoolExecutor(max_workers=len(requests)) as pool:
            futures=[pool.submit(submit,client,request[1],request[2]) for client,request in zip(clients,requests)]; barrier.wait(timeout=15)
            return sorted(future.result(timeout=30) for future in futures)
    def test_concurrent_allocations_cannot_double_assign_responder_on_sqlite(self):
        emergencies=[Emergency.objects.create(reference=f'DR-RACE-VOL-{i}',reporter=self.official,category='Flood',description='Race test',location=f'Ward {i}',status='ACCEPTED',accepted_by=self.gov) for i in (1,2)]
        responder=User.objects.create_user('race.volunteer@test.local',password='password123'); Profile.objects.create(user=responder,role='GOV_VOL',organization=self.gov,approval='APPROVED')
        requests=[(self.official.pk,e.pk,{'kind':'VOL','user_ids':[responder.pk]}) for e in emergencies]
        statuses=self._race_assignments(requests)
        if not Assignment.objects.filter(user=responder,status__in=['ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','BLOCKED']).exists():
            retry=Client(); retry.force_login(self.official)
            statuses.append(retry.post(f'/api/emergencies/{emergencies[0].pk}/assign/',data=json.dumps(requests[0][2]),content_type='application/json').status_code)
        self.assertEqual(statuses.count(200),1)
        self.assertEqual(Assignment.objects.filter(user=responder,status__in=['ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','BLOCKED']).count(),1)
    def test_concurrent_allocations_cannot_double_book_vehicle_on_sqlite(self):
        emergencies=[Emergency.objects.create(reference=f'DR-RACE-DRV-{i}',reporter=self.official,category='Flood',description='Race test',location=f'Ward {i}',status='ACCEPTED',accepted_by=self.gov) for i in (1,2)]
        drivers=[User.objects.create_user(f'race.driver{i}@test.local',password='password123') for i in (1,2)]
        for driver in drivers: Profile.objects.create(user=driver,role='GOV_DRIVER',organization=self.gov,approval='APPROVED')
        Vehicle.objects.create(organization=self.gov,registration='RACE-VAN-1',kind='Relief van',capacity=12)
        requests=[(self.official.pk,e.pk,{'kind':'DRIVER','user_ids':[driver.pk]}) for e,driver in zip(emergencies,drivers)]
        statuses=self._race_assignments(requests)
        self.assertIn(statuses,([200,409],[409,409]))
        active_dispatches=Dispatch.objects.filter(vehicle__registration='RACE-VAN-1',status__in=['ASSIGNED','ACCEPTED','IN_TRANSIT','EXCEPTION']).count()
        self.assertLessEqual(active_dispatches,1)
        if 200 in statuses: self.assertEqual(active_dispatches,1)

class WorkflowTests(TestCase):
    def setUp(self):
        self.gov=Organization.objects.create(name='Test Response Office',kind='GOV')
        self.ngo=Organization.objects.create(name='Test Relief NGO',kind='NGO')
        self.official=User.objects.create_user('official@test.local',password='password123'); Profile.objects.create(user=self.official,role='GOV',organization=self.gov,approval='APPROVED')
        self.coordinator=User.objects.create_user('ngo@test.local',password='password123'); Profile.objects.create(user=self.coordinator,role='NGO',organization=self.ngo,approval='APPROVED')
        self.citizen=User.objects.create_user('citizen@test.local',password='password123'); Profile.objects.create(user=self.citizen,role='CITIZEN')
    def post(self,c,path,data):
        data=dict(data)
        if path=='/api/emergencies/' and data.get('location') and not data.get('address'):
            data['address']=data.pop('location'); data['district']='Ludhiana'
        if path=='/api/shelters/' and data.get('location') and not data.get('district'):
            data['address']=data['location']; data['district']='Ludhiana'
            if data.get('latitude') is None: data['latitude']=30.901
            if data.get('longitude') is None: data['longitude']=75.857
        return c.post(path,data=json.dumps(data),content_type='application/json')
    def test_production_settings_reject_missing_or_placeholder_secret_keys(self):
        for secret in ('','replace-for-deployment','short-secret'):
            env=os.environ.copy(); env['DJANGO_DEBUG']='0'; env['DJANGO_SECRET_KEY']=secret
            result=subprocess.run([sys.executable,'-c','import drras.settings'],env=env,capture_output=True,text=True)
            self.assertNotEqual(result.returncode,0,secret)
            self.assertIn('DJANGO_SECRET_KEY',result.stderr)
    def test_sqlite_is_the_only_configured_database(self):
        self.assertEqual(connection.vendor,'sqlite')
        self.assertEqual(connection.settings_dict['ENGINE'],'django.db.backends.sqlite3')
