    def test_ngo_allocation_requires_government_authorization_before_execution(self):
        emergency=Emergency.objects.create(reference='DR-AUTH-001',reporter=self.citizen,category='Flood',description='Evacuation support',location='NGO ward',status='ACCEPTED',accepted_by=self.ngo,required_skills='First aid')
        responder=User.objects.create_user('auth.volunteer@test.local',password='password123'); Profile.objects.create(user=responder,role='NGO_VOL',organization=self.ngo,approval='APPROVED',details={'skills':'First aid'})
        ngo=Client(); ngo.force_login(self.coordinator)
        direct=self.post(ngo,f'/api/emergencies/{emergency.pk}/assign/',{'kind':'VOL','user_ids':[responder.pk]})
        self.assertEqual(direct.status_code,200,direct.content)
        self.assertEqual(Assignment.objects.filter(emergency=emergency,user=responder,organization=self.ngo).count(),1)
        responder2=User.objects.create_user('auth.volunteer2@test.local',password='password123'); Profile.objects.create(user=responder2,role='NGO_VOL',organization=self.ngo,approval='APPROVED',details={'skills':'First aid'})
        created=self.post(ngo,'/api/allocations/',{'emergency_id':emergency.pk,'kind':'VOL','user_ids':[responder2.pk],'task_instructions':'Assist with household evacuation'})
        self.assertEqual(created.status_code,201); authorization=AllocationAuthorization.objects.get(pk=created.json()['authorization']['id']); self.assertEqual(authorization.status,'PENDING')
        self.assertEqual(Assignment.objects.filter(emergency=emergency).count(),1)
        gov=Client(); gov.force_login(self.official)
        queue=gov.get('/api/allocations/').json()['results']; self.assertEqual(queue[0]['id'],authorization.pk); self.assertEqual(queue[0]['users'][0]['availability'],'AVAILABLE')
        pending_user=User.objects.create_user('pending.reviewer@test.local',password='password123'); Profile.objects.create(user=pending_user,role='GOV',organization=self.gov,approval='PENDING')
        pending=Client(); pending.force_login(pending_user); self.assertEqual(self.post(pending,f'/api/allocations/{authorization.pk}/review/',{'decision':'APPROVED'}).status_code,403)
        self.assertEqual(self.post(gov,f'/api/allocations/{authorization.pk}/review/',{'decision':'APPROVED','note':'Authorized for this response'}).status_code,200)
        self.assertEqual(Assignment.objects.filter(emergency=emergency).count(),1)
        authorization.refresh_from_db(); self.assertEqual(authorization.status,'APPROVED')
        self.assertEqual(self.post(ngo,f'/api/allocations/{authorization.pk}/execute/',{}).status_code,200)
        authorization.refresh_from_db(); assignment=Assignment.objects.get(emergency=emergency,user=responder2)
        self.assertEqual(Assignment.objects.filter(emergency=emergency).count(),2)
        self.assertEqual(authorization.status,'EXECUTED'); self.assertEqual(assignment.organization,self.ngo); self.assertEqual(assignment.assigned_by,self.coordinator)
        self.assertEqual(list(authorization.history.values_list('event_type',flat=True)),['SUBMITTED','APPROVED','EXECUTED'])
        self.assertEqual(self.post(ngo,f'/api/allocations/{authorization.pk}/execute/',{}).status_code,409)
