    def test_driver_cancellation_records_reason_notifies_and_releases_dispatch(self):
        driver=User.objects.create_user('cancel.self.driver@test.local',password='password123'); Profile.objects.create(user=driver,role='GOV_DRIVER',organization=self.gov,approval='APPROVED')
        vehicle=Vehicle.objects.create(organization=self.gov,registration='TEST-SELF-CANCEL-1',kind='Relief van',capacity=8)
        emergency=Emergency.objects.create(reference='DR-SELF-CANCEL-001',reporter=self.citizen,category='Flood',description='Supply transport',location='Test town',status='IN_PROGRESS',accepted_by=self.gov)
        assignment=Assignment.objects.create(emergency=emergency,user=driver,organization=self.gov,kind='DRIVER',status='IN_PROGRESS')
        dispatch=Dispatch.objects.create(emergency=emergency,driver=driver,organization=self.gov,vehicle=vehicle,destination='Test town',status='IN_TRANSIT')
        client=Client(); client.force_login(driver)
        self.assertEqual(self.post(client,f'/api/assignments/{assignment.pk}/',{'status':'CANCELLED'}).status_code,400)
        cancelled=self.post(client,f'/api/assignments/{assignment.pk}/',{'status':'CANCELLED','cancellation_reason':'Vehicle tyre damaged; cannot safely continue.'})
        self.assertEqual(cancelled.status_code,200)
        assignment.refresh_from_db(); dispatch.refresh_from_db(); emergency.refresh_from_db()
        self.assertEqual(assignment.status,'CANCELLED'); self.assertEqual(assignment.history.get().note,'Vehicle tyre damaged; cannot safely continue.')
        self.assertEqual(dispatch.status,'CANCELLED'); self.assertEqual(dispatch.history.get().note,'Vehicle tyre damaged; cannot safely continue.')
        self.assertEqual(emergency.status,'IN_PROGRESS')
        self.assertTrue(emergency.history.filter(event_type='ASSIGNMENT_CANCELLED',note='Vehicle tyre damaged; cannot safely continue.').exists())
        self.assertTrue(Notification.objects.filter(user=self.citizen,title='Responder assignment cancelled').exists())
        self.assertTrue(Notification.objects.filter(user=self.official,title='Responder assignment cancelled').exists())
        self.assertFalse(Assignment.objects.filter(user=driver,status__in=['ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','BLOCKED']).exists())
        coordinator=Client(); coordinator.force_login(self.official)
        reassigned=self.post(coordinator,f'/api/emergencies/{emergency.pk}/assign/',{'kind':'DRIVER','user_ids':[driver.pk],'vehicle_ids':[vehicle.pk],'pickup_location':'Central depot','cargo_details':'Replacement relief load'})
        self.assertEqual(reassigned.status_code,200)
        assignment.refresh_from_db(); dispatch.refresh_from_db()
        self.assertEqual(assignment.status,'ASSIGNED'); self.assertEqual(list(assignment.history.values_list('status',flat=True)),['CANCELLED','ASSIGNED'])
        self.assertEqual(dispatch.status,'ASSIGNED'); self.assertEqual(list(dispatch.history.values_list('status',flat=True)),['CANCELLED','ASSIGNED'])
        self.assertEqual(dispatch.cargo_details,'Replacement relief load')
        self.assertTrue(Notification.objects.filter(user=driver,title='New response assignment').exists())
