    def test_advisory_draft_edit_publish_withdraw_archive_and_history(self):
        official=Client(); official.force_login(self.official)
        expiry=(timezone.now()+timedelta(days=1)).isoformat()
        created=self.post(official,'/api/advisories/',{'title':'River watch','category':'Flood','body':'Initial details','location':'North ward','severity':'HIGH','expires_at':expiry,'action':'SAVE'})
        self.assertEqual(created.status_code,201); advisory=Advisory.objects.get(pk=created.json()['advisory']['id']); self.assertFalse(advisory.published)
        self.assertEqual(advisory.category,'Flood'); self.assertIsNotNone(advisory.expires_at)
        self.assertEqual(Client().get('/api/advisories/').json()['results'],[])
        managed=official.get('/api/advisories/?manage=1').json()['results'][0]; self.assertEqual(managed['state'],'DRAFT'); self.assertEqual([x['event_type'] for x in managed['history']],['DRAFTED'])
        edited=official.patch(f'/api/advisories/{advisory.pk}/',data=json.dumps({'action':'SAVE','title':'River watch update','category':'Evacuation','body':'Move to the east shelter.','location':'North ward','severity':'CRITICAL','expires_at':(timezone.now()+timedelta(days=2)).isoformat()}),content_type='application/json')
        self.assertEqual(edited.status_code,200); advisory.refresh_from_db(); self.assertEqual((advisory.title,advisory.severity,advisory.category),('River watch update','CRITICAL','Evacuation'))
        published=official.patch(f'/api/advisories/{advisory.pk}/',data=json.dumps({'action':'PUBLISH'}),content_type='application/json')
        self.assertEqual(published.status_code,200); self.assertTrue(advisory.history.filter(event_type='PUBLISHED').exists()); self.assertTrue(Notification.objects.filter(user=self.citizen,title='New public advisory').exists())
        public=Client().get('/api/advisories/').json()['results']; self.assertEqual(public[0]['severity'],'CRITICAL')
        self.assertEqual(official.patch(f'/api/advisories/{advisory.pk}/',data=json.dumps({'action':'WITHDRAW'}),content_type='application/json').status_code,200)
        self.assertEqual(Client().get('/api/advisories/').json()['results'],[])
        archived=official.patch(f'/api/advisories/{advisory.pk}/',data=json.dumps({'action':'ARCHIVE'}),content_type='application/json')
        self.assertEqual(archived.status_code,200); self.assertEqual(archived.json()['advisory']['state'],'ARCHIVED')
        self.assertEqual(list(advisory.history.values_list('event_type',flat=True)),['DRAFTED','UPDATED','PUBLISHED','WITHDRAWN','ARCHIVED'])
